window.VF2_UNITS = {"1":{"unit":1,"code":"VF2-U01","title":"TRAVEL & TRANSPORT","startNumber":1,"endNumber":17,"entries":[{"number":1,"term":"voyage (n) ~ trip (n) ~ journey (n)","spoken":"voyage , trip , journey","ipa":"voyage /ˈvɔɪədʒ/ · trip /trɪp/ · journey /ˈdʒɝːni/","type":"noun · word family","meaning":"hành trình dài, nhất là bằng đường biển ~ chuyến đi, thường có đi rồi về ~ hành trình từ nơi này đến nơi khác","definition":"A voyage is a long journey, especially by sea; a trip is a visit or journey in general, while journey emphasizes travelling from one place to another.","note":"voyage chủ yếu là hành trình dài bằng đường biển; trip là chuyến đi nói chung, còn journey nhấn mạnh quá trình di chuyển.","example":"The six-week voyage was a much longer journey than their usual weekend trips."},{"number":2,"term":"excursion (n)","spoken":"excursion","ipa":"excursion /ɪˈkskɝːʒən/","type":"noun","meaning":"chuyến đi tham quan","definition":"A short organized trip made for pleasure, education, or a particular purpose.","note":"excursion là chuyến đi ngắn có tổ chức, thường để tham quan hoặc học tập.","example":"During the school excursion, students visited a coastal museum and interviewed a local guide."},{"number":3,"term":"sight (n) ~ view (n) ~ scenery (n)","spoken":"sight , view , scenery","ipa":"sight /saɪt/ · view /vjuː/ · scenery /ˈsiːnɚi/","type":"noun · word family","meaning":"cảnh hoặc điều nhìn thấy ~ quang cảnh nhìn từ một vị trí ~ phong cảnh thiên nhiên nói chung","definition":"A sight is something seen; a view is what can be seen from a particular place, while scenery is the general natural landscape.","note":"sight là cảnh/cảnh tượng cụ thể; view là tầm nhìn từ một vị trí; scenery là phong cảnh chung, không đếm được.","example":"The waterfall was an unforgettable sight, and the viewpoint offered a wide view of the surrounding scenery."},{"number":4,"term":"territory (n)","spoken":"territory","ipa":"territory /ˈtɛrɪˌtɔːri/","type":"noun","meaning":"lãnh thổ","definition":"An area of land controlled by a country, government, or group.","note":"","example":"The treaty defines the territory controlled by each country and protects the shared border."},{"number":5,"term":"fare (n) # fine (v,n) # fee (n) ~ charge (n) # ticket (n)","spoken":"fare , fine , fee , charge , ticket","ipa":"fare /fɛr/ · fine /faɪn/ · fee /fiː/ · charge /tʃɑːrdʒ/ · ticket /ˈtɪkət/","type":"verb · noun · word family","meaning":"cước/phí đi lại # phạt; tiền phạt # khoản phí phải trả ~ khoản tiền được tính # vé","definition":"Fare is the cost of a journey; a fine is a financial penalty; a fee or charge is money paid for a service; a ticket gives the right to travel or enter.","note":"fare là tiền đi tàu xe; fine là tiền phạt; fee/charge là khoản phí dịch vụ; ticket là vé.","example":"The train fare was $20, but he also paid a fine for travelling without a valid ticket; the booking fee was separate."},{"number":6,"term":"arrive in/at + place ~ reach + place","spoken":"arrive in or at + place , reach + place","ipa":"arrive /ɚˈaɪv/ · place /pleɪs/ · reach /riːtʃ/","type":"phrase / pattern · word family","meaning":"đến một địa điểm, dùng in/at trước địa điểm ~ đến hoặc đặt chân tới một địa điểm, không dùng in/at","definition":"Arrive in/at and reach both mean to get to a place, but reach takes no preposition.","note":"arrive at + địa điểm nhỏ, arrive in + thành phố/quốc gia; reach + địa điểm, không có at/in.","example":"We arrived at the station at noon and reached the hotel before the heavy rain began."},{"number":7,"term":"border (n)","spoken":"border","ipa":"border /ˈbɔːrdɚ/","type":"noun","meaning":"biên giới, ranh giới","definition":"The official line separating two countries or areas; also the edge of something.","note":"","example":"Officers checked every vehicle before it crossed the international border."},{"number":8,"term":"advance (v) to a place · advance (v,n)","spoken":"advance to a place , advance","ipa":"advance /əˈdvæns/ · place /pleɪs/","type":"verb · noun · phrase / pattern · word family","meaning":"tiến về một địa điểm · tiến bộ, phát triển; sự tiến bộ","definition":"To move forward towards a place; as a noun or general verb, advance also means progress or improvement.","note":"advance to/towards là tiến về phía trước; an advance còn có thể là khoản trả trước hoặc một bước tiến.","example":"The rescue team advanced towards the village as weather conditions improved."},{"number":9,"term":"recognize (v) · recognition (n)","spoken":"recognize , recognition","ipa":"recognize /ˈrɛkəˌɡnaɪz/ · recognition /ˌrɛkəˈɡnɪʃən/","type":"verb · noun · word family","meaning":"nhận ra, công nhận · sự nhận ra, sự công nhận","definition":"To identify somebody or something from previous knowledge, or to formally accept its status or value.","note":"","example":"I recognized the building from the photograph, and its official recognition as a historic site followed later."},{"number":10,"term":"broad (a) · broaden (v) · breadth (n)","spoken":"broad , broaden , breadth","ipa":"broad /brɔːd/ · broaden /ˈbrɔːdən/ · breadth /brɛdθ/","type":"verb · noun · adjective · word family","meaning":"rộng · làm rộng, mở rộng · chiều rộng, phạm vi rộng","definition":"Broad means wide or covering many subjects; broaden means to make wider; breadth is the noun.","note":"","example":"The university broadened the course to cover a broad range of topics in greater breadth."},{"number":11,"term":"inhabitant (n) ~ resident (n) ~ dweller (n)","spoken":"inhabitant , resident , dweller","ipa":"inhabitant /ɪˈnhæbətənt/ · resident /ˈrɛzɪdənt/ · dweller /ˈdwɛlɚ/","type":"noun · word family","meaning":"cư dân, người sinh sống tại một nơi","definition":"A person who lives in a particular place.","note":"resident nhấn mạnh nơi cư trú; inhabitant là người/sinh vật sống ở một nơi; dweller thường đi trong từ ghép như city dweller.","example":"Many residents work in the city, while long-term inhabitants still describe themselves as village dwellers."},{"number":12,"term":"make for ~ head for","spoken":"make for , head for","ipa":"make /meɪk/ · head /hɛd/","type":"phrasal verb · word family","meaning":"đi về phía, hướng tới","definition":"To move or travel in the direction of a place.","note":"","example":"After checking the map, the cyclists headed for the coast and made for the nearest campsite."},{"number":13,"term":"drop sb off >< pick sb up","spoken":"drop somebody off , pick somebody up","ipa":"drop /drɑːp/ · off /ɔːf/ · pick /pɪk/ · up /ʌp/","type":"phrasal verb · word family","meaning":"đưa ai đến rồi cho xuống xe · đón ai lên xe","definition":"To drop somebody off is to take them somewhere and let them out of a vehicle; to pick somebody up is to collect them.","note":"drop sb off là chở ai đến rồi cho xuống; trái nghĩa tự nhiên trong ngữ cảnh xe cộ là pick sb up.","example":"The driver dropped the passengers off at the terminal and picked them up there that evening."},{"number":14,"term":"see sb off","spoken":"see somebody off","ipa":"see /siː/ · off /ɔːf/","type":"phrasal verb","meaning":"tiễn ai đó","definition":"To go with somebody to their departure point and say goodbye.","note":"Giữ đúng mẫu từ đi kèm: see sb off.","example":"Families gathered at the station to see the exchange students off."},{"number":15,"term":"pick sb up","spoken":"pick somebody up","ipa":"pick /pɪk/ · up /ʌp/","type":"phrasal verb","meaning":"đón ai đó","definition":"To collect somebody in a vehicle from an agreed place.","note":"Giữ đúng mẫu từ đi kèm: pick sb up.","example":"The coach will pick us up outside the library at half past six."},{"number":16,"term":"pull in # pull over","spoken":"pull in , pull over","ipa":"pull /pʊl/ · over /ˈoʊvɚ/","type":"phrasal verb · word family","meaning":"phương tiện công cộng đến và dừng lại · người lái xe tấp vào lề và dừng lại","definition":"Pull in means that a train or other vehicle arrives and stops; pull over means that a driver moves to the side of the road and stops.","note":"pull in dùng khi tàu/xe đến và dừng; pull over là tấp xe vào lề.","example":"The train pulled in as a taxi pulled over outside the station."},{"number":17,"term":"set out ~ set off","spoken":"set out , set off","ipa":"set /sɛt/ · out /aʊt/ · off /ɔːf/","type":"phrasal verb · word family","meaning":"khởi hành, bắt đầu chuyến đi","definition":"To begin a journey or start doing something with a particular aim.","note":"","example":"The climbers set off before sunrise and set out to reach the summit by noon."}],"pronunciationFocus":[{"entryNumber":2,"points":[{"category":"word-stress","note":"excursion /ɪˈkskɝːʒən/: trọng âm chính ở âm tiết thứ hai"}]},{"entryNumber":6,"points":[{"category":"linking","note":"arrive‿in và arrive‿at: nối /v/ sang nguyên âm đầu của từ sau"}]},{"entryNumber":9,"points":[{"category":"word-stress","note":"recognition /ˌrɛkəˈɡnɪʃən/: trọng âm chính ở âm tiết thứ ba"}]},{"entryNumber":10,"points":[{"category":"common-error","note":"breadth /brɛdθ/ dùng nguyên âm /ɛ/, khác broad /brɔːd/"},{"category":"final-sound","note":"breadth /brɛdθ/: giữ rõ cụm âm cuối /dθ/"}]}]}};
